import{_ as a,o,c as t,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-MSAVE-Command.md","filePath":"manual-en/Matrix-MSAVE-Command.md","lastUpdated":1785684581000}'),d={name:"manual-en/Matrix-MSAVE-Command.md"};function s(i,e,c,r,m,l){return o(),t("div",null,[...e[0]||(e[0]=[n(`<h4 id="_16-4-12-the-msave-command" tabindex="-1">16.4.12 The <code>MSAVE</code> Command <a class="header-anchor" href="#_16-4-12-the-msave-command" aria-label="Permalink to &quot;16.4.12 The \`MSAVE\` Command&quot;">​</a></h4><pre><code>MSAVE _expression_
      /TYPE={COV _|_ CORR _|_ MEAN _|_ STDDEV _|_ N _|_ COUNT}
      [/FACTOR=_expression_]
      [/SPLIT=_expression_]
      [/OUTFILE=_file_]
      [/VARIABLES=_variable_ …]
      [/SNAMES=_variable_ …]
      [/FNAMES=_variable_ …].
</code></pre><p>The <code>MSAVE</code> command evaluates the <em>expression</em> specified just after the command name, and writes the resulting matrix to a matrix file (see <a href="./Matrix-Files">Matrix Files</a>).</p><p>The <code>TYPE</code> subcommand is required. It specifies the <code>ROWTYPE_</code> to write along with this matrix.</p><p>The <code>FACTOR</code> and <code>SPLIT</code> subcommands are required on the first <code>MSAVE</code> if and only if the matrix file has factor or split variables, respectively. After that, their values are carried along from one <code>MSAVE</code> command to the next in syntax order as defaults. Each one takes an expression that must evaluate to a vector with the same number of entries as the matrix has factor or split variables, respectively. Each <code>MSAVE</code> only writes data for a single combination of factor and split variables, so many <code>MSAVE</code> commands (or one inside a loop) may be needed to write a complete set.</p><p>The remaining <code>MSAVE</code> subcommands define the format of the matrix file. All of the <code>MSAVE</code> commands within a given matrix program write to the same matrix file, so these subcommands are only meaningful on the first <code>MSAVE</code> command within a matrix program. (If they are given again on later <code>MSAVE</code> commands, then they must have the same values as on the first.)</p><p>The <code>OUTFILE</code> subcommand specifies the name or handle of the matrix file to be written. Output must go to an external file, not a data set or the active file.</p><p>The <code>VARIABLES</code> subcommand specifies a comma-separated list of the names of the continuous variables to be written to the matrix file. The <code>TO</code> keyword can be used to define variables named with consecutive integer suffixes. These names become column names and names that appear in <code>VARNAME_</code> in the matrix file. <code>ROWTYPE_</code> and <code>VARNAME_</code> are not allowed on <code>VARIABLES</code>. If <code>VARIABLES</code> is omitted, then PSPP uses the names <code>COL1</code>, <code>COL2</code>, and so on.</p><p>The <code>FNAMES</code> subcommand may be used to supply a comma-separated list of factor variable names. The default names are <code>FAC1</code>, <code>FAC2</code>, and so on.</p><p>The <code>SNAMES</code> subcommand can supply a comma-separated list of split variable names. The default names are <code>SPL1</code>, <code>SPL2</code>, and so on.</p>`,10)])])}const f=a(d,[["render",s]]);export{p as __pageData,f as default};
